/**
 * HVACBizPro IMPORT + PARSE (Gmail -> Raw -> Jobs)
 *
 * RULES:
 * 1) NEVER overwrite existing rows in "HVACBizPro Jobs"
 *    - Existing parsed rows are identified by Message ID in column A
 *    - If Message ID already exists in Jobs column A, skip it
 *    - This preserves any manual edits in the Jobs tab
 *
 * 2) Raw import still appends only new emails into "HVACBizPro Raw Emails"
 *    - Message ID key in Raw column A
 *
 * 3) NO duplicates
 *    - Raw dedupes by Message ID in column A
 *    - Jobs dedupes by Message ID in column A
 *
 * SHEETS:
 * - Raw:  "HVACBizPro Raw Emails"
 *   A=Message ID, B=Gmail Date, C=From, D=Subject, E=Plain Body
 *
 * - Jobs: "HVACBizPro Jobs"
 *   A=Message ID (parse key)
 */

const HVACBIZPRO = {
  SPREADSHEET_ID: "",

  SHEET_RAW: "HVACBizPro Raw Emails",
  SHEET_JOBS: "HVACBizPro Jobs",

  GMAIL_QUERY: 'from:communications@hvacbizpro.com subject:"Financial Summary"',
  THREAD_PAGE_SIZE: 200,
  MAX_PAGES: 50,
  WRITE_BATCH_SIZE: 200
};

function hvacBizPro_ImportAndParse() {
  logExec_("RUN_START", "hvacBizPro_ImportAndParse");

  const ss = getSpreadsheet_();
  const shRaw = getOrCreateSheet_(ss, HVACBIZPRO.SHEET_RAW, rawHeaders_());
  const shJobs = getOrCreateSheet_(ss, HVACBIZPRO.SHEET_JOBS, jobHeaders_());

  // Ensure headers exist
  shRaw.getRange(1, 1, 1, rawHeaders_()[0].length).setValues(rawHeaders_());
  shRaw.setFrozenRows(1);

  shJobs.getRange(1, 1, 1, jobHeaders_()[0].length).setValues(jobHeaders_());
  shJobs.setFrozenRows(1);

  const imported = hvacBizPro_ImportRaw_(shRaw);
  logExec_("IMPORT_DONE", `newRaw=${imported}`);

  const appended = hvacBizPro_ParseAndAppendJobs_(shRaw, shJobs);
  logExec_("PARSE_DONE", `newJobs=${appended}`);

  logExec_("RUN_END", "hvacBizPro_ImportAndParse");
}

function hvacBizPro_ImportRaw_(shRaw) {
  const existingMsgIds = loadExistingIdsFromColumn_(shRaw, 1); // Raw col A
  logExec_("RAW_EXISTING_IDS", `count=${existingMsgIds.size}`);

  const buffer = [];
  let totalThreads = 0;
  let totalMessages = 0;
  let newRows = 0;

  for (let page = 0; page < HVACBIZPRO.MAX_PAGES; page++) {
    const start = page * HVACBIZPRO.THREAD_PAGE_SIZE;
    const threads = GmailApp.search(HVACBIZPRO.GMAIL_QUERY, start, HVACBIZPRO.THREAD_PAGE_SIZE);

    logExec_("THREAD_PAGE", `page=${page + 1} fetched=${threads.length} start=${start}`);
    if (!threads.length) break;

    totalThreads += threads.length;

    for (const thread of threads) {
      for (const msg of thread.getMessages()) {
        totalMessages++;

        const msgId = msg.getId();
        if (existingMsgIds.has(msgId)) continue;

        const date = msg.getDate();
        const from = msg.getFrom() || "";
        const subject = msg.getSubject() || "";
        const plainBody = normalizeBody_(msg.getPlainBody() || "");

        existingMsgIds.add(msgId);
        buffer.push([msgId, date, from, subject, plainBody]);
        newRows++;

        if (buffer.length >= HVACBIZPRO.WRITE_BATCH_SIZE) {
          appendRows_(shRaw, buffer);
          buffer.length = 0;
          logExec_("RAW_PROGRESS", `newRaw=${newRows} scannedMsgs=${totalMessages}`);
        }
      }
    }
  }

  if (buffer.length) appendRows_(shRaw, buffer);

  logExec_("RAW_SUMMARY", `threads=${totalThreads} scannedMsgs=${totalMessages} newRaw=${newRows}`);
  return newRows;
}

function hvacBizPro_ParseAndAppendJobs_(shRaw, shJobs) {
  const rawLastRow = shRaw.getLastRow();
  if (rawLastRow < 2) return 0;

  const rawValues = shRaw.getRange(2, 1, rawLastRow - 1, 5).getValues();
  const COL_MSG_ID = 0;
  const COL_DATE = 1;
  const COL_SUBJECT = 3;
  const COL_BODY = 4;

  // Existing parsed keys from Jobs column A
  const parsedMsgIds = loadExistingIdsFromColumn_(shJobs, 1);
  logExec_("JOBS_EXISTING_KEYS", `count=${parsedMsgIds.size}`);

  const rowsToAppend = [];
  let appended = 0;
  let skippedAlreadyParsed = 0;
  let skippedNotMatch = 0;

  for (const row of rawValues) {
    const msgId = String(row[COL_MSG_ID] ?? "").trim();
    if (!msgId) continue;

    // Never overwrite existing Jobs rows
    if (parsedMsgIds.has(msgId)) {
      skippedAlreadyParsed++;
      continue;
    }

    const gmailDate = row[COL_DATE];
    const subject = row[COL_SUBJECT] || "";
    const body = normalizeBody_(String(row[COL_BODY] || ""));

    if (!body || !body.toUpperCase().includes("PROPOSAL") || !body.toUpperCase().includes("CUSTOMER")) {
      skippedNotMatch++;
      continue;
    }

    const p = parseHvacBizProBody_(body);

    const out = fixRowToLength_([
      msgId,                    // A Message ID = parse key
      gmailDate,                // B Gmail Date
      subject,                  // C Subject

      p.proposal || "",         // D
      p.sales_rep || "",        // E
      p.opened || "",           // F
      p.closed || "",           // G
      p.install || "",          // H

      p.customer_name || "",    // I
      p.address1 || "",         // J
      p.city || "",             // K
      p.state || "",            // L
      p.zip || "",              // M
      p.tel || "",              // N
      p.email || "",            // O

      p.selling_price || "",    // P
      p.equipment || "",        // Q
      p.parts || "",            // R
      p.services || "",         // S
      p.labor || "",            // T
      p.tax || "",              // U
      p.labor_hours || "",      // V
      p.cogs || "",             // W
      p.gross_margin || "",     // X
      p.gross_profit || "",     // Y
      p.cost_of_financing || "",// Z
      p.payment_method || "",   // AA
      p.commissions || "",      // AB
      p.proposal_link || ""     // AC
    ], jobHeaders_()[0].length);

    rowsToAppend.push(out);
    parsedMsgIds.add(msgId);
    appended++;
  }

  if (rowsToAppend.length) {
    appendRows_(shJobs, rowsToAppend);
    logExec_("JOBS_APPENDED", `count=${rowsToAppend.length}`);
  }

  logExec_("JOBS_PARSE_SUMMARY", `appended=${appended} skippedParsed=${skippedAlreadyParsed} skippedNotMatch=${skippedNotMatch}`);
  return appended;
}

/* =========================
 * PARSER
 * ========================= */

function parseHvacBizProBody_(body) {
  const cleaned = body.replace(/\*/g, "");
  const lines = cleaned.split("\n").map(l => l.trim()).filter(Boolean);

  const r = {
    proposal: findValueAfterLabel_(lines, "PROPOSAL"),
    sales_rep: findValueAfterLabel_(lines, "SALES REP"),
    opened: findValueAfterLabel_(lines, "OPENED"),
    closed: findValueAfterLabel_(lines, "CLOSED"),
    install: findValueAfterLabel_(lines, "INSTALL"),

    customer_name: null,
    address1: null,
    city: null,
    state: null,
    zip: null,
    tel: null,
    email: null,

    selling_price: pickValueAfterPercentFromLines_(lines, "Selling Price"),
    equipment: pickValueAfterPercentFromLines_(lines, "Equipment"),
    parts: pickValueAfterPercentFromLines_(lines, "Parts"),
    services: pickValueAfterPercentFromLines_(lines, "Services"),
    labor: pickValueAfterPercentFromLines_(lines, "Labor"),
    tax: pickValueAfterPercentFromLines_(lines, "Tax"),
    labor_hours: pickLastNumberFromLines_(lines, "Labor Hours"),
    cogs: pickValueAfterPercentFromLines_(lines, "COGS"),
    gross_margin: pickValueAfterPercentFromLines_(lines, "Gross Margin"),
    gross_profit: pickLastNumberFromLines_(lines, "Gross Profit $"),
    cost_of_financing: pickLastNumberFromLines_(lines, "Cost of financing"),
    payment_method: null,
    commissions: pickLastNumberFromLines_(lines, "Commissions"),

    proposal_link: extractProposalLink_(cleaned)
  };

  const custIdx = findIndexStartsWith_(lines, "CUSTOMER");
  if (custIdx >= 0) {
    const rawName = lines[custIdx].replace(/^CUSTOMER\s*/i, "").trim();
    r.customer_name = toProperCase_(rawName);

    r.address1 = lines[custIdx + 1] || null;

    const cs = parseCityStateZipLoose_(lines[custIdx + 2] || "");
    r.city = cs.city;
    r.state = cs.state;
    r.zip = cs.zip;

    for (let i = custIdx + 1; i < Math.min(lines.length, custIdx + 15); i++) {
      const l = lines[i];
      if (/^Tel\s*:/i.test(l)) r.tel = l.replace(/^Tel\s*:\s*/i, "").trim();
      if (/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i.test(l)) r.email = l.trim();
    }
  }

  const payLine = findLineStartsWith_(lines, "Payment Method");
  if (payLine) {
    const m = payLine.match(/Pay by:\s*(.+)$/i);
    r.payment_method = m ? m[1].trim() : payLine.replace(/^Payment Method/i, "").trim();
  }

  return r;
}

/* =========================
 * HEADERS
 * ========================= */

function rawHeaders_() {
  return [[
    "Message ID",
    "Gmail Date",
    "From",
    "Subject",
    "Plain Body"
  ]];
}

function jobHeaders_() {
  return [[
    "Message ID","Gmail Date","Subject",
    "Proposal","Sales Rep","Opened","Closed","Install",
    "Customer Name","Address Line 1","City","State","ZIP","Telephone","Email",
    "Selling Price","Equipment","Parts","Services","Labor","Tax","Labor Hours",
    "COGS","Gross Margin","Gross Profit $","Cost of financing","Payment Method",
    "Commissions","Proposal Link"
  ]];
}

/* =========================
 * HELPERS
 * ========================= */

function toProperCase_(str) {
  if (!str) return str;
  return String(str)
    .toLowerCase()
    .split(/\s+/)
    .map(w => w ? w[0].toUpperCase() + w.slice(1) : "")
    .join(" ");
}

function fixRowToLength_(row, len) {
  while (row.length < len) row.push("");
  return row.slice(0, len);
}

function findValueAfterLabel_(l, k) {
  return (findLineStartsWith_(l, k) || "").replace(new RegExp("^" + k + "\\s*", "i"), "").trim() || null;
}

function pickValueAfterPercentFromLines_(l, k) {
  const x = findLineStartsWith_(l, k);
  if (!x) return null;
  return (x.match(/%\s*([\d,]+)/) || [])[1] || (x.match(/([\d,]+)\s*$/) || [])[1] || null;
}

function pickLastNumberFromLines_(l, k) {
  const x = findLineStartsWith_(l, k);
  return x ? (x.match(/([\d,]+)\s*$/) || [])[1] : null;
}

function findLineStartsWith_(l, k) {
  k = k.toLowerCase();
  return l.find(x => x.toLowerCase().startsWith(k)) || null;
}

function findIndexStartsWith_(l, k) {
  k = k.toLowerCase();
  return l.findIndex(x => x.toLowerCase().startsWith(k));
}

function parseCityStateZipLoose_(l) {
  const m = l.match(/^(.+?),\s*([A-Z]{2})\s+(\d{5})$/i);
  return { city: m ? m[1] : null, state: m ? m[2] : null, zip: m ? m[3] : null };
}

function extractProposalLink_(b) {
  const m = b.match(/https?:\/\/hvacbizpro\.com\/proposals\/hardcopy\/\S+/i);
  return m ? m[0] : null;
}

function normalizeBody_(plain) {
  let t = String(plain || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  t = t.replace(/\t+/g, " ");
  t = t.replace(/[ ]{2,}/g, " ");
  return t.trim();
}

function logExec_(tag, msg) {
  const line = `${new Date().toISOString()} | ${tag} | ${msg}`;
  Logger.log(line);
  console.log(line);
}

function getSpreadsheet_() {
  return HVACBIZPRO.SPREADSHEET_ID
    ? SpreadsheetApp.openById(HVACBIZPRO.SPREADSHEET_ID)
    : SpreadsheetApp.getActiveSpreadsheet();
}

function getOrCreateSheet_(ss, name, headers2d) {
  let sh = ss.getSheetByName(name);
  if (!sh) sh = ss.insertSheet(name);

  const headerLen = headers2d[0].length;
  sh.getRange(1, 1, 1, headerLen).setValues(headers2d);
  sh.setFrozenRows(1);

  return sh;
}

function appendRows_(sheet, rows2d) {
  if (!rows2d || rows2d.length === 0) return;
  sheet.getRange(sheet.getLastRow() + 1, 1, rows2d.length, rows2d[0].length).setValues(rows2d);
}

function loadExistingIdsFromColumn_(sheet, colIndex) {
  const lastRow = sheet.getLastRow();
  const set = new Set();
  if (lastRow < 2) return set;

  const vals = sheet.getRange(2, colIndex, lastRow - 1, 1).getValues();
  for (const [v] of vals) {
    const s = String(v ?? "").trim();
    if (s) set.add(s);
  }
  return set;
}

/**
 * Fast refresh using one batch write via Sheets Advanced Service.
 * Row 1 preserved. Writes A2:I in a single call. Clears tail implicitly.
 * DEST: "Actual Costs" tab in spreadsheet 1MnkDZSNcNR4RFiPE3-QfSVtEvZ_M_qS_KdRHGiFyAvY
 */
function refreshMaterialCostImport() {
  const DEST_FILE_ID = '1MnkDZSNcNR4RFiPE3-QfSVtEvZ_M_qS_KdRHGiFyAvY';
  const DEST_SHEET_NAME = 'Material Cost Import';

  const SOURCE_IDS = [
    '1-HFrkzF3Mqf0WxZhoSXEArc_3ZSzWT6NB-XBjD0bl9Q',
    '1OSdrTRwBv4ZRWbueTM7lPguID8d9OehFJkQEimNlstU',
    '1_frrVtIqkfg5hVtglhHTNK8yIO7TnUO4liC8uW0pQAE',
  ];
  const KEEP_SET = new Set(['Equipment', 'Stock Equipment', 'Special Order']);

  const t0 = Date.now();

  // ---- Destination spreadsheet/sheet (NOT the active spreadsheet)
  const destSS = SpreadsheetApp.openById(DEST_FILE_ID);
  const dst =
    destSS.getSheetByName(DEST_SHEET_NAME) || destSS.insertSheet(DEST_SHEET_NAME);

  function safe(v) {
    return v == null ? '' : v;
  }

  function fmtMDY(d) { // MM/DD/YYYY
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const y = d.getFullYear();
    return `${m}/${day}/${y}`;
  }

  function normalizeDatesInMatrix(rows) {
    for (let r = 0; r < rows.length; r++) {
      const row = rows[r];
      for (let c = 0; c < row.length; c++) {
        const v = row[c];
        if (v instanceof Date && !isNaN(v)) row[c] = fmtMDY(v);
      }
    }
    return rows;
  }

  function retry_(label, fn, tries = 4, baseMs = 300) {
    let last;
    for (let i = 0; i < tries; i++) {
      try {
        const t = Date.now();
        const r = fn();
        console.log(`[time] ${label} ${Date.now() - t}ms try${i + 1}/${tries}`);
        return r;
      } catch (e) {
        last = e;
        const wait = Math.min(baseMs * Math.pow(2, i), 5000);
        console.log(`[retry] ${label} ${i + 1}/${tries} wait ${wait}ms`, String(e));
        Utilities.sleep(wait);
      }
    }
    throw last;
  }

  // ---- Build columns in memory (no writes yet)
  const A = [], B = [], C = [], D = [], E = [], F = [], G = [], H = [], I = [];

  SOURCE_IDS.forEach((id, idx) => {
    const srcLabel = `src#${idx + 1}`;
    const src = retry_(`${srcLabel}: openById`, () => SpreadsheetApp.openById(id));

    // Released: B..Q → B,E,H,Q
    retry_(`${srcLabel}: Released B..Q`, () => {
      const sh = src.getSheetByName('Released'); if (!sh) return;
      const last = sh.getLastRow(); if (last < 3) return;
      const block = sh.getRange(3, 2, last - 2, 16).getValues();
      block.forEach(r => {
        I.push(safe(r[0]));   // B
        B.push(safe(r[3]));   // E
        A.push(safe(r[6]));   // H
        C.push(safe(r[15]));  // Q
      });
    });

    // Received: B..U → B,E,H,T,U
    retry_(`${srcLabel}: Received B..U`, () => {
      const sh = src.getSheetByName('Received'); if (!sh) return;
      const last = sh.getLastRow(); if (last < 3) return;
      const block = sh.getRange(3, 2, last - 2, 20).getValues();
      block.forEach(r => {
        const b = safe(r[0]);            // B
        const cat = String(safe(r[3]));  // E
        const h = safe(r[6]);            // H
        const t = safe(r[18]);           // T
        const u = safe(r[19]);           // U
        F.push(h);
        G.push(t);
        if (KEEP_SET.has(cat)) {
          D.push(h);
          E.push(u);
          H.push(b);
        } else {
          D.push('');
          E.push('');
          H.push('');
        }
      });
    });
  });

  // ---- Assemble one rectangular matrix A2:I and write once
  const prevLast = dst.getLastRow(); // includes header
  const newHeights = [A.length, B.length, C.length, D.length, E.length, F.length, G.length, H.length, I.length];
  const newMax = Math.max(...newHeights);
  const prevHeight = Math.max(0, prevLast - 1);
  const height = Math.max(newMax, prevHeight);

  const rows2D = new Array(height);
  for (let r = 0; r < height; r++) {
    rows2D[r] = [
      A[r] ?? '', B[r] ?? '', C[r] ?? '',
      D[r] ?? '', E[r] ?? '', F[r] ?? '',
      G[r] ?? '', H[r] ?? '', I[r] ?? ''
    ];
  }

  // Force MM/DD/YYYY for any Date cells
  normalizeDatesInMatrix(rows2D);

  // Single call via Advanced Service. Overwrites A2:I(1+height) in one request.
  const range = `'${DEST_SHEET_NAME}'!A2:I${height + 1}`;
  retry_('values.update A2:I', () =>
    Sheets.Spreadsheets.Values.update(
      { range, majorDimension: 'ROWS', values: rows2D },
      DEST_FILE_ID,
      range,
      { valueInputOption: 'RAW' }
    ),
    3, 400
  );

  const totalMillis = Date.now() - t0;
  console.log(`[summary] totalMillis: ${totalMillis}, rows: ${height}`);
}

function QuickMode() {
  // Step 4: Generate the manday map
  const mandayMap = generateMandayMap();
  SpreadsheetApp.getActive().toast('Step 4 Completed: Manday map generated.', 'Step 4 of 5', 3);

  // Step 5: Search for IDs and calculate mandays
  calculateMandaysForIDs(mandayMap);
  SpreadsheetApp.getActive().toast('Step 5 Completed: Mandays calculated for all Pipedrive IDs.', 'Step 5 of 5', 3);

  // Notify completion
  Logger.log('Manday calculation process completed.');
  SpreadsheetApp.getActive().toast('Manday calculation process completed.', 'Done', 5);
}

function MandayRecalculation() {
  // Step 1: Clear the 'Week Key' sheet
  clearWeekKeySheet();
  SpreadsheetApp.getActive().toast('Step 1 Completed: Week Key sheet cleared.', 'Step 1 of 5', 3);

  // Step 2: Copy only grey cells from 'Formula Friendly Schedule' to 'Week Key'
  copyGreyCellsToWeekKey();
  SpreadsheetApp.getActive().toast('Step 2 Completed: Grey cells copied to Week Key sheet.', 'Step 2 of 5', 3);

  // Step 3: Replace tech names with manday values in 'Week Key'
  replaceTechNamesWithMandayValues();
  SpreadsheetApp.getActive().toast('Step 3 Completed: Tech names replaced with manday values.', 'Step 3 of 5', 3);

  // Step 4: Generate the manday map
  const mandayMap = generateMandayMap();
  SpreadsheetApp.getActive().toast('Step 4 Completed: Manday map generated.', 'Step 4 of 5', 3);

  // Step 5: Search for IDs and calculate mandays
  calculateMandaysForIDs(mandayMap);
  SpreadsheetApp.getActive().toast('Step 5 Completed: Mandays calculated for all Pipedrive IDs.', 'Step 5 of 5', 3);

  // Notify completion
  Logger.log('Manday calculation process completed.');
  SpreadsheetApp.getActive().toast('Manday calculation process completed.', 'Done', 5);
}

function clearWeekKeySheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const weekKeySheet = ss.getSheetByName('Week Key');
  if (!weekKeySheet) {
    Logger.log('Error: Week Key sheet is missing.');
    return;
  }
  weekKeySheet.clearContents();
  Logger.log('Week Key sheet has been cleared.');
}

function copyGreyCellsToWeekKey() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const formulaSheet = ss.getSheetByName('Formula Friendly Schedule');
  const weekKeySheet = ss.getSheetByName('Week Key');
  if (!formulaSheet || !weekKeySheet) {
    Logger.log('Error: One or more required sheets are missing.');
    return;
  }

  const lastRow = formulaSheet.getLastRow();
  const lastCol = formulaSheet.getLastColumn();

  const dataRange = formulaSheet.getRange(1, 1, lastRow, lastCol);
  const dataValues = dataRange.getValues();
  const bgColors = dataRange.getBackgrounds();

  const greyCellValues = dataValues.map(row => row.map(() => ''));

  const knownGreyCell = formulaSheet.getRange('A4');
  const greyColorCode = knownGreyCell.getBackground();

  // Explicitly skip rows 2 and 3 (index 1 and 2)
  for (let i = 0; i < dataValues.length; i++) {
    if (i === 1 || i === 2) continue; // skip rows 2 & 3 outright
    for (let j = 0; j < dataValues[0].length; j++) {
      if (bgColors[i][j] === greyColorCode) {
        greyCellValues[i][j] = dataValues[i][j].toString();
      }
    }
  }

  weekKeySheet.getRange(1, 1, greyCellValues.length, lastCol).setValues(greyCellValues);
  Logger.log('Grey cells copied to Week Key sheet (rows 2 and 3 skipped).');
}

function replaceTechNamesWithMandayValues() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const weekKeySheet = ss.getSheetByName('Week Key');
  const techListSheet = ss.getSheetByName('TechList');
  const formulaSheet = ss.getSheetByName('Formula Friendly Schedule');

  if (!weekKeySheet || !techListSheet || !formulaSheet) {
    Logger.log('Error: One or more required sheets are missing.');
    return;
  }

  // ---- helper: "Week - 48 (2025)" -> 2025*100 + 48
  function weekOrdinal(label) {
    if (!label) return NaN;
    const s = String(label).trim();
    const m = s.match(/^Week\s*-\s*(\d{1,2})\s*\((\d{4})\)$/i);
    if (!m) return NaN;
    const w = parseInt(m[1], 10);
    const y = parseInt(m[2], 10);
    return (isNaN(w) || isNaN(y)) ? NaN : y * 100 + w;
  }

  // ======================
  // 1) TechList: build per-tech series from A4:A and B4:P
  // ======================

  // Use last row based on column A (names), not whole sheet.
  const lastTechRow = techListSheet.getRange('A:A').getLastRow();
  const techRowCount = Math.max(0, lastTechRow - 3); // rows 4+

  if (techRowCount === 0) {
    Logger.log('No tech rows found in TechList (A4:A is empty).');
  }

  const headerWeeksRaw = techListSheet.getRange('B2:P2').getValues()[0];
  const headerWeeks = headerWeeksRaw.map(v => v ? String(v).trim() : '');
  const headerKeys = headerWeeks.map(weekOrdinal);

  const techNames = techRowCount
    ? techListSheet.getRange(4, 1, techRowCount, 1).getValues().flat()
    : [];
  const techValues = techRowCount
    ? techListSheet.getRange(4, 2, techRowCount, 16).getValues() // B..P
    : [];

  const techSeries = {};
  for (let r = 0; r < techRowCount; r++) {
    const nameNorm = String(techNames[r] || '').trim().toLowerCase();
    if (!nameNorm) continue;

    const rowVals = techValues[r].slice();
    // left-fill: each new value applies at that week and all weeks after
    let lastSeen = null;
    for (let c = 0; c < rowVals.length; c++) {
      const v = rowVals[c];
      if (v === '' || v == null) {
        rowVals[c] = lastSeen;
      } else {
        lastSeen = v;
      }
    }
    techSeries[nameNorm] = rowVals;
  }

  function getTechValueForWeek(techNameNorm, weekLabel) {
    const series = techSeries[techNameNorm];
    if (!series) return 0.5;

    const targetKey = weekOrdinal(weekLabel);
    if (isNaN(targetKey)) return 0.5;

    // last header <= target
    let idx = -1;
    for (let i = 0; i < headerKeys.length; i++) {
      const k = headerKeys[i];
      if (!isNaN(k) && k <= targetKey) idx = i;
    }
    if (idx === -1) idx = 0;

    const num = Number(series[idx]);
    return isNaN(num) ? 0.5 : num;
  }

  // ======================
  // 2) Read Week Key + week labels with limited width
  // ======================
  const wkLastRow = weekKeySheet.getLastRow();
  if (wkLastRow < 2) {
    Logger.log('Week Key has no data to convert.');
    return;
  }

  const schedLastCol = formulaSheet.getLastColumn(); // authoritative width
  if (schedLastCol < 1) {
    Logger.log('Formula Friendly Schedule has no columns.');
    return;
  }

  // Week labels from Week Key row 1 (should be "Week - 48 (2025)" etc.)
  const headerRow = weekKeySheet.getRange(1, 1, 1, schedLastCol).getValues()[0];
  const weekLabels = headerRow.map(v => v ? String(v).trim() : '');

  // Tech names / values currently in Week Key (rows 2..end, cols 1..schedLastCol)
  const bodyValues = weekKeySheet.getRange(2, 1, wkLastRow - 1, schedLastCol).getValues();

  // Prepare output values: same size as existing Week Key (wkLastRow x schedLastCol)
  const outValues = new Array(wkLastRow);
  // row 1: keep week labels as-is
  outValues[0] = weekLabels.slice();

  // rows 2+: insert numeric values
  for (let r = 0; r < bodyValues.length; r++) {
    const rowOut = new Array(schedLastCol);
    const rowIn = bodyValues[r];
    for (let c = 0; c < schedLastCol; c++) {
      const raw = rowIn[c];

      // Empty stays empty
      if (raw === '' || raw == null) {
        rowOut[c] = '';
        continue;
      }

      // If already numeric (Week Key already converted), keep it. Don't re-map to 0.5.
      if (typeof raw === 'number') {
        rowOut[c] = raw;
        continue;
      }

      // Text: treat as tech name and map through TechList
      const techName = String(raw).trim();
      const norm = techName.toLowerCase();
      const weekLabel = weekLabels[c];
      const value = getTechValueForWeek(norm, weekLabel);

      rowOut[c] = value;

      if (value === 0.5 && !techSeries[norm]) {
        Logger.log(`Unrecognized tech "${techName}" at Week Key r${r + 2}, week "${weekLabel}". Assigned 0.5`);
      }
    }
    outValues[r + 1] = rowOut;
  }

  // ======================
  // 3) Write back once (no notes, no extra columns)
  // ======================
  const writeRange = weekKeySheet.getRange(1, 1, wkLastRow, schedLastCol);
  writeRange.clearContent(); // keep formats
  writeRange.setValues(outValues);

  Logger.log('Week Key updated: single column per week, numeric manday values only.');
}

function generateMandayMap() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const weekKeySheet = ss.getSheetByName('Week Key');
  if (!weekKeySheet) {
    Logger.log('Error: Week Key sheet is missing.');
    return {};
  }

  const lastRow = weekKeySheet.getLastRow();
  const lastCol = weekKeySheet.getLastColumn();

  const weekLabelsRaw = weekKeySheet.getRange(1, 1, 1, lastCol).getValues()[0];
  const weekLabels = weekLabelsRaw.map(label => label ? label.toString().trim() : '');

  const mandayMap = {};
  for (let j = 0; j < weekLabels.length; j++) {
    const weekLabel = weekLabels[j];
    if (!weekLabel) continue;
    mandayMap[weekLabel] = [];

    for (let i = 1; i < Math.min(75, lastRow); i++) {
      let cellValue = weekKeySheet.getRange(i + 1, j + 1).getValue();
      if (cellValue === '' || cellValue == null) {
        cellValue = 0.5;
      } else {
        cellValue = Number(cellValue);
      }
      mandayMap[weekLabel].push(cellValue);
    }
    Logger.log(`Week Key "${weekLabel}": Values from rows 2-75: ${mandayMap[weekLabel].join(', ')}`);
  }

  Logger.log('Manday map generated successfully.');
  return mandayMap;
}

function calculateMandaysForIDs(mandayMap) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const formulaSheet = ss.getSheetByName('Formula Friendly Schedule');
  const jobTracking = ss.getSheetByName('Job Tracking');
  const techListSheet = ss.getSheetByName('TechList');

  if (!formulaSheet || !jobTracking || !techListSheet) {
    Logger.log('Error: Required sheet(s) missing.');
    return;
  }

  // Job Tracking columns:
  // A = Job Name
  // B = Pipedrive ID
  // F = Status
  // G = Start Date
  // H = Completed Date
  // P = Actual Mandays (output)
  const JT_COL_ID = 2;         // B
  const JT_COL_STATUS = 6;     // F
  const JT_COL_START = 7;      // G
  const JT_COL_COMPLETED = 8;  // H
  const JT_COL_MANDAYS = 16;   // O (output + existing mandays for skip)

  const jtLastRow = jobTracking.getLastRow();
  if (jtLastRow < 2) {
    Logger.log('Job Tracking has no data rows.');
    return;
  }

  // Read A:L so we have id/status/dates/mandays
  const jtData = jobTracking.getRange(2, 1, jtLastRow - 1, JT_COL_MANDAYS).getValues();
  const idInfo = [];

  jtData.forEach((row, idx) => {
    const id = row[JT_COL_ID - 1]; // B
    const status = row[JT_COL_STATUS - 1]; // F
    const startDateRaw = row[JT_COL_START - 1]; // G
    const completedRaw = row[JT_COL_COMPLETED - 1]; // H
    const existingMandays = row[JT_COL_MANDAYS - 1]; // L

    if (id && id.toString().trim() !== '') {
      idInfo.push({
        id: id.toString().trim(),
        startDateRaw,
        status,
        completedRaw,
        existingMandays,
        rowNumber: idx + 2, // because jtData starts at row 2
      });
    }
  });

  // "Today" from TechList!R1 (existing behavior)
  const today = techListSheet.getRange('R1').getValue();
  if (!(today instanceof Date)) {
    Logger.log('Error: Invalid date in TechList!R1.');
    return;
  }

  // Cutoff for future weeks (existing logic)
  const cutoffDate = new Date(today);
  cutoffDate.setMonth(cutoffDate.getMonth() + 2);

  // Two-week lookback for skipping completed jobs
  const twoWeeksAgo = new Date(today);
  twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);

  const lastRow = formulaSheet.getLastRow();
  const lastCol = formulaSheet.getLastColumn();
  const scheduleData = formulaSheet.getRange(1, 1, lastRow, lastCol).getValues();
  const weekLabels = scheduleData[0].map(label => label ? label.toString().trim() : '');
  const dateRow = scheduleData[2];

  // Precompute cell A1 notations for logging
  const cellNotations = [];
  for (let row = 1; row < Math.min(75, scheduleData.length); row++) {
    cellNotations[row] = [];
    for (let col = 0; col < weekLabels.length; col++) {
      cellNotations[row][col] = formulaSheet.getRange(row + 1, col + 1).getA1Notation();
    }
  }

  const checkedCellsLog = [];

  idInfo.forEach(({ id, startDateRaw, status, completedRaw, existingMandays, rowNumber }) => {
    // Skip rule: Completed, completed > 2 weeks ago, and already has mandays > 0
    let skip = false;
    let completedDate = null;

    if (completedRaw instanceof Date && !isNaN(completedRaw)) {
      completedDate = completedRaw;
    } else if (completedRaw) {
      const tmp = new Date(completedRaw);
      if (!isNaN(tmp)) completedDate = tmp;
    }

    if (
      status === 'Completed' &&
      completedDate &&
      completedDate <= twoWeeksAgo &&
      Number(existingMandays) > 0
    ) {
      skip = true;
    }

    if (skip) {
      Logger.log(`Skipping ID ${id} at row ${rowNumber}: Completed, older than 2 weeks, mandays already set (${existingMandays}).`);
      return;
    }

    // Normal manday calculation for non-skipped rows
    if (!startDateRaw) {
      Logger.log(`Start date missing for ID ${id} at row ${rowNumber}`);
      return;
    }

    const startDate = new Date(startDateRaw);
    if (isNaN(startDate.getTime())) {
      Logger.log(`Invalid start date for ID ${id} at row ${rowNumber}`);
      return;
    }

    let totalMandays = 0;
    const idVariants = getIdVariants(id);

    for (let col = 0; col < weekLabels.length; col++) {
      const weekLabel = weekLabels[col];
      const weekDate = dateRow[col];

      if (!weekLabel || !weekDate || isNaN(new Date(weekDate))) continue;

      const currentWeekDate = new Date(weekDate);

      if (currentWeekDate >= startDate && currentWeekDate <= cutoffDate) {
        for (let row = 1; row < Math.min(75, scheduleData.length); row++) {
          const cellValue = scheduleData[row][col];
          if (cellValue) {
            const cellText = cellValue.toString().trim();
            const match = idVariants.some(variant =>
              new RegExp(`\\b${variant}\\b`, 'i').test(cellText)
            );

            if (match) {
              const mandayRowIndex = row - 1;
              const mandayValue = (mandayMap[weekLabel] && mandayMap[weekLabel][mandayRowIndex])
                ? mandayMap[weekLabel][mandayRowIndex]
                : 0.5;
              totalMandays += Number(mandayValue);
              checkedCellsLog.push([id, 'Formula Friendly Schedule', cellNotations[row][col], weekLabel, cellValue]);
            }
          }
        }
      }
    }

    // Write mandays to Job Tracking column L
    jobTracking.getRange(rowNumber, JT_COL_MANDAYS).setValue(totalMandays);
    Logger.log(`Mandays for ID ${id} (row ${rowNumber}): ${totalMandays}`);
    SpreadsheetApp.getActive().toast(`ID ${id} calculated: ${totalMandays} mandays`, 'Manday Calculation', 5);
  });

  logCheckedCells(checkedCellsLog);
}

function getIdVariants(id) {
  const idStr = id.toString().trim();
  return idStr.includes('/') ? idStr.split('/').map(s => s.trim()) : [idStr];
}

function logCheckedCells(logData) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let logSheet = ss.getSheetByName('CheckedLog');

  if (!logSheet) {
    logSheet = ss.insertSheet('CheckedLog');
  } else {
    logSheet.clearContents();
  }

  const headers = [['ID', 'Sheet', 'Cell', 'Week Label', 'Checked Value']];
  const outputData = headers.concat(logData);

  logSheet.getRange(1, 1, outputData.length, outputData[0].length).setValues(outputData);
  Logger.log('CheckedLog sheet updated.');
}

/**
 * DEPOSIT RECEIVED (Gmail) -> Job Tracking (Google Sheet)
 *
 * FIX: write to the FIRST SAFE BLANK ROW (not "lastRow+1")
 * Safe row rule:
 * - If column A is blank OR column B is blank, that row is considered writable.
 *
 * Writes:
 * - Col A = Job Name
 * - Col B = Pipedrive ID
 *
 * Skip:
 * - If ID already exists anywhere in column B, skip it.
 */

const TARGET_SPREADSHEET_ID = "1MnkDZSNcNR4RFiPE3-QfSVtEvZ_M_qS_KdRHGiFyAvY";
const TARGET_SHEET_NAME = "Job Tracking";

const DAYS_LOOKBACK = 180;
const GMAIL_QUERY_BASE = 'from:me subject:"Deposit Received"';

const THREAD_PAGE_SIZE = 100;
const MAX_PAGES = 25;

function logNewDealsFromEmail() {
  logExec_("RUN_START", "Deposit Received -> Job Tracking");

  const ss = SpreadsheetApp.openById(TARGET_SPREADSHEET_ID);
  const sh = ss.getSheetByName(TARGET_SHEET_NAME);
  if (!sh) throw new Error(`Sheet not found: ${TARGET_SHEET_NAME}`);

  const maxRows = sh.getMaxRows();
  const dataAB = sh.getRange(2, 1, maxRows - 1, 2).getValues(); // A2:B

  // Existing IDs set + first safe writable row
  const existingIds = new Set();
  let firstWritableIndex = -1; // index into dataAB (0-based), row = index+2

  for (let i = 0; i < dataAB.length; i++) {
    const aVal = String(dataAB[i][0] ?? "").trim();
    const bVal = String(dataAB[i][1] ?? "").trim();

    if (bVal) existingIds.add(bVal);

    // SAFE ROW: if A blank OR B blank, it is writable
    if (firstWritableIndex === -1 && (!aVal || !bVal)) {
      firstWritableIndex = i;
    }
  }

  logExec_("EXISTING_IDS", `Count=${existingIds.size}`);
  logExec_("FIRST_WRITABLE_ROW", firstWritableIndex === -1 ? "NONE" : String(firstWritableIndex + 2));

  if (firstWritableIndex === -1) {
    throw new Error("No writable rows found (A blank OR B blank). Add more rows or clear gaps.");
  }

  const gmailQuery = `${GMAIL_QUERY_BASE} newer_than:${DAYS_LOOKBACK}d`;
  logExec_("GMAIL_QUERY", gmailQuery);

  let totalThreads = 0;
  let inspected = 0;
  let skippedNoId = 0;
  let skippedNoName = 0;
  let skippedDup = 0;

  const newRows = []; // [jobName, id]

  for (let page = 0; page < MAX_PAGES; page++) {
    const start = page * THREAD_PAGE_SIZE;
    const threads = GmailApp.search(gmailQuery, start, THREAD_PAGE_SIZE);

    logExec_("THREAD_PAGE", `page=${page + 1} fetched=${threads.length} start=${start}`);
    if (!threads.length) break;

    totalThreads += threads.length;

    for (const thread of threads) {
      for (const msg of thread.getMessages()) {
        inspected++;

        const body = msg.getPlainBody() || "";
        const jobNameRaw = extractDepositName_(body);
        const idStr = extractDepositPipedriveId_(body);

        if (!idStr) {
          skippedNoId++;
          continue;
        }

        const jobName = toProperCase_(jobNameRaw);
        if (!jobName) {
          skippedNoName++;
          continue;
        }

        if (existingIds.has(idStr)) {
          skippedDup++;
          continue;
        }

        existingIds.add(idStr);
        newRows.push([jobName, idStr]);
        logExec_("QUEUED", `${idStr} | ${jobName}`);
      }
    }
  }

  logExec_("SUMMARY", `Threads=${totalThreads} Messages=${inspected} New=${newRows.length} NoID=${skippedNoId} NoName=${skippedNoName} Dup=${skippedDup}`);

  if (!newRows.length) {
    logExec_("RUN_END", "Nothing to write");
    return;
  }

  // Write sequentially into the first writable row, filling downward.
  // (Assumes you want to fill the table top-down without skipping gaps.)
  const startRow = firstWritableIndex + 2;
  const endRow = startRow + newRows.length - 1;

  if (endRow > sh.getMaxRows()) {
    throw new Error(`Not enough rows to write. Need rows ${startRow}..${endRow}, maxRows=${sh.getMaxRows()}`);
  }

  sh.getRange(startRow, 1, newRows.length, 2).setValues(newRows);

  logExec_("WROTE", `Rows=${newRows.length} startRow=${startRow}`);
  logExec_("RUN_END", "Done");
}

/* =========================
 * Parsing helpers
 * ========================= */

function extractDepositName_(body) {
  if (!body) return "";
  const lines = body.split(/\r?\n/).map(l => l.trim());

  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];

    // Same-line: "Deposit has been received for: JOB NAME"
    let m = l.match(/^Deposit has been received for\s*:\s*(.+)$/i);
    if (m && m[1]) return m[1].trim();

    // Next-line:
    if (/^Deposit has been received for\s*:\s*$/i.test(l)) {
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j]) return lines[j];
      }
      return "";
    }
  }
  return "";
}

function extractDepositPipedriveId_(body) {
  if (!body) return "";

  // Inline match
  let m = body.match(/Pipedrive ID\s*:\s*\(?\s*(\d+)\s*\)?/i);
  if (m) return String(m[1]).trim();

  // Next-line match
  const lines = body.split(/\r?\n/).map(l => l.trim());
  for (let i = 0; i < lines.length; i++) {
    if (/^Pipedrive ID\s*:\s*$/i.test(lines[i])) {
      for (let j = i + 1; j < Math.min(lines.length, i + 5); j++) {
        const mm = lines[j].match(/\(?\s*(\d+)\s*\)?/);
        if (mm) return String(mm[1]).trim();
      }
    }
  }

  return "";
}

/* =========================
 * Formatting + logging
 * ========================= */

function toProperCase_(str) {
  if (!str) return "";
  return String(str)
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .map(w => (w ? w[0].toUpperCase() + w.slice(1) : ""))
    .join(" ");
}

function logExec_(tag, msg) {
  const line = `${new Date().toISOString()} | ${tag} | ${msg}`;
  Logger.log(line);
  console.log(line);
}

function findFirstAndLastAppearanceDates() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const formulaSheet = ss.getSheetByName('Formula Friendly Schedule');
  const jobTracking = ss.getSheetByName('Job Tracking');

  if (!formulaSheet || !jobTracking) {
    Logger.log('Missing sheet.');
    return;
  }

  const scheduleData = formulaSheet.getDataRange().getValues();
  const dateRow = scheduleData[2]; // row 3 (0-based index 2)
  const scheduleCols = scheduleData[0].length;

  // IDs from Job Tracking column B
  const ids = jobTracking.getRange('B2:B').getValues().map(r => r[0]);

  const output = []; // [firstDate, lastDate]

  ids.forEach(rawId => {
    const id = rawId ? rawId.toString().trim() : '';
    if (!id) {
      output.push(['', '']);
      return;
    }

    const idVariants = getIdVariants(id);

    let firstDate = null;
    let lastDate = null;

    for (let col = 0; col < scheduleCols; col++) {
      let foundInThisCol = false;

      for (let row = 1; row < Math.min(75, scheduleData.length); row++) {
        const cellVal = scheduleData[row][col];
        if (!cellVal) continue;

        const cellText = cellVal.toString().trim();
        if (idVariants.some(v => new RegExp(`\\b${escapeRegex_(v)}\\b`, 'i').test(cellText))) {
          foundInThisCol = true;
          break;
        }
      }

      if (foundInThisCol) {
        const date = dateRow[col];
        if (date instanceof Date) {
          if (!firstDate) firstDate = date;
          lastDate = date; // keep updating, so it ends as the last found
        }
      }
    }

    output.push([firstDate || '', lastDate || '']);
  });

  // Write to Job Tracking: C = first, D = last (starting row 2)
  jobTracking.getRange(2, 3, output.length, 2).setValues(output);
  Logger.log('First (C) and last (D) appearance dates written.');
}

/**
 * Escapes regex special chars for safe RegExp building.
 */
function escapeRegex_(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Material List Link Finder
 *
 * Reads:
 * - Sheet: "Job Tracking"
 * - ID column: B
 * - Company column: D  (used to pick root folder)
 *
 * Writes:
 * - Link column: Y
 *
 * Behavior:
 * - Scans upward starting from the LAST non-empty ID in column B
 * - Only processes rows where Y is blank OR "No list found" OR "No List Created"
 * - If runtime is near limit, saves progress and exits
 * - Next run resumes from the last row processed (continues scanning upward)
 */

const ML_CONFIG = {
  SHEET: 'Job Tracking',
  COL_ID: 2,        // B
  COL_COMPANY: 4,   // D
  COL_LINK: 25,     // Y
  START_ROW: 2,

  // Progress persistence
  PROP_KEY_ROW: 'ML_LAST_ROW',

  // Time budget
  MAX_RUNTIME_MS: 5.5 * 60 * 1000, // stop before Apps Script hard limit
};

function populateMaterialListLinks_JobTracking() {
  const t0 = Date.now();
  Logger.log('populateMaterialListLinks_JobTracking() start');

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(ML_CONFIG.SHEET);
  if (!sheet) {
    Logger.log(`ERROR: Missing "${ML_CONFIG.SHEET}" sheet`);
    return;
  }

  const lastRowById = findLastNonEmptyRowInColumn_(sheet, ML_CONFIG.COL_ID, ML_CONFIG.START_ROW);
  if (lastRowById < ML_CONFIG.START_ROW) {
    Logger.log('No IDs found in column B.');
    return;
  }

  // Resume row: if stored row is invalid/outside current range, reset to lastRowById
  const props = PropertiesService.getScriptProperties();
  let resumeRow = Number(props.getProperty(ML_CONFIG.PROP_KEY_ROW) || '');
  if (!resumeRow || resumeRow > lastRowById || resumeRow < ML_CONFIG.START_ROW) {
    resumeRow = lastRowById;
  }

  Logger.log(`Last non-empty ID row in B: ${lastRowById}`);
  Logger.log(`Starting scan at row: ${resumeRow} (upward)`);

  let processed = 0;
  let updated = 0;

  for (let r = resumeRow; r >= ML_CONFIG.START_ROW; r--) {
    // Time guard
    if (Date.now() - t0 > ML_CONFIG.MAX_RUNTIME_MS) {
      props.setProperty(ML_CONFIG.PROP_KEY_ROW, String(r));
      Logger.log(`TIME_GUARD: saving resume row ${r} and exiting`);
      Logger.log(`Processed=${processed} Updated=${updated}`);
      return;
    }

    const id = sheet.getRange(r, ML_CONFIG.COL_ID).getDisplayValue().toString().trim();
    if (!id) continue; // skip blanks in the ID column

    const linkVal = sheet.getRange(r, ML_CONFIG.COL_LINK).getDisplayValue().toString().trim();

    // Only process blanks or no-list markers
    if (!(linkVal === '' || /^(no\s+list\s+found|no\s+list\s+created)$/i.test(linkVal))) {
      continue;
    }

    const companyRaw = sheet.getRange(r, ML_CONFIG.COL_COMPANY).getDisplayValue().toString().trim();
    const folderName = getFolderNameForCompany_(companyRaw);

    processed++;

    if (!folderName) {
      Logger.log(`Row ${r}: unknown company "${companyRaw}" (ID=${id}), skipping`);
      continue;
    }

    Logger.log(`Row ${r}: searching ID="${id}", folder="${folderName}"`);

    let foundUrl = '';
    const folders = DriveApp.getFoldersByName(folderName);
    if (folders.hasNext()) {
      const root = folders.next();
      foundUrl = searchFolderRecursively_(root, id, []); // keep keywords empty unless you want prioritization
    } else {
      Logger.log(`Row ${r}: root folder not found: "${folderName}"`);
    }

    sheet.getRange(r, ML_CONFIG.COL_LINK).setValue(foundUrl || 'No list found');
    updated++;
  }

  // Completed full scan; clear resume pointer
  props.deleteProperty(ML_CONFIG.PROP_KEY_ROW);
  Logger.log(`populateMaterialListLinks_JobTracking() complete. Processed=${processed} Updated=${updated}`);
}

/* =========================
 * Helpers
 * ========================= */

function findLastNonEmptyRowInColumn_(sheet, col, startRow) {
  const lastRow = sheet.getLastRow();
  if (lastRow < startRow) return 0;

  // Read the whole column slice once
  const vals = sheet.getRange(startRow, col, lastRow - startRow + 1, 1).getDisplayValues();

  for (let i = vals.length - 1; i >= 0; i--) {
    if (String(vals[i][0] || '').trim() !== '') return startRow + i;
  }
  return 0;
}

// Map D value to the correct root folder
function getFolderNameForCompany_(companyRaw) {
  if (!companyRaw) return '';
  const v = companyRaw.toLowerCase();

  if (v.indexOf('bell mech') !== -1) return 'Material Lists - Bell Mechanical';
  if (v.indexOf('pack timco') !== -1) return 'Material Lists - Pack Timco';
  if (v.indexOf('metro') !== -1) return 'Material Lists - Metro Aire';
  if (v.indexOf('mck') !== -1) return 'Material Lists - MCK Plumbing';

  return '';
}

// ─── HELPER: check if filename contains any keyword ───
function filenameMatchesKeywords_(fileNameLower, keywords) {
  if (!keywords || keywords.length === 0) return false;
  for (var i = 0; i < keywords.length; i++) {
    if (fileNameLower.indexOf(keywords[i]) !== -1) return true;
  }
  return false;
}

// ─── HELPER: process a list of Drive Files; return URL if code matched in C5 ───
function checkFilesForCode_(files, code) {
  while (files.length) {
    var file = files.shift();
    try {
      var ssFile = SpreadsheetApp.openById(file.getId());
      var matIn = ssFile.getSheetByName('Material Input');
      if (!matIn) {
        Logger.log('      ' + file.getName() + ': no "Material Input" sheet');
        continue;
      }
      var c5 = matIn.getRange('C5').getDisplayValue().toString().trim();
      if (c5 === code) {
        Logger.log('      MATCH in file: ' + file.getName());
        return file.getUrl();
      }
    } catch (e) {
      Logger.log('      Error opening "' + file.getName() + '": ' + e);
    }
  }
  return '';
}

// ─── HELPER: recursively search folders ───
function searchFolderRecursively_(folder, code, keywords) {
  var prefer = [];
  var others = [];
  var it = folder.getFilesByType(MimeType.GOOGLE_SHEETS);
  while (it.hasNext()) {
    var f = it.next();
    var nameLower = f.getName().toLowerCase();
    if (filenameMatchesKeywords_(nameLower, keywords)) {
      prefer.push(f);
    } else {
      others.push(f);
    }
  }
  if (prefer.length || others.length) {
    Logger.log('    Folder "' + folder.getName() + '": ' + prefer.length + ' prioritized, ' + others.length + ' other files');
  }

  var url = checkFilesForCode_(prefer, code);
  if (url) return url;

  url = checkFilesForCode_(others, code);
  if (url) return url;

  var subs = folder.getFolders();
  while (subs.hasNext()) {
    var sub = subs.next();
    Logger.log('    Descending into subfolder: ' + sub.getName());
    var found = searchFolderRecursively_(sub, code, keywords);
    if (found) return found;
  }

  return '';
}

/**
 * Subcontractor Estimates (PMT IMPORT OVERRIDE FIRST, RAW EMAIL BACKUP) + INSTALL ADDRESS -> COL B
 *
 * TARGET SHEET: "Subcontractor Estimates"
 * A Job Name | B Install Address | C Electrical ($) | D Drilling ($) | E Permitting ($) | F Labor ($) | G Snippets
 *
 * OVERRIDE RULE (FIRST):
 * 1) Look for exact matching Job Name in column A of tab "PMT Import"
 * 2) If found AND AE (Drilling) is NON-ZERO:
 *    - Set Drilling ($) = value from column AE of PMT Import (same row)
 *    - Set Electrical/Permitting/Labor = 0
 *    - Set B = "-"
 *    - Set Snippets = "PMT Import AE"
 *    - Next job
 * 3) If found but AE is zero/blank: IGNORE PMT and parse emails normally.
 *
 * EMAIL RULE (BACKUP):
 * - Use sheet "HVACBizPro Raw Emails" (D subject, E body)
 * - Pick ONE best matching email (no summing across many emails)
 * - Parse priced items "@ $amount" and categorize by canonical similarity
 * - Extract Install Address from the chosen body and write to column B
 *
 * ADDRESS RULE (YOUR CHANGE):
 * - Find "Install Address"
 * - Take the text AFTER the LAST COMMA within that Install Address block
 *   Example: "123 Main St, Town, NY 12345" -> "NY 12345"
 *
 * LOGGING:
 * - Execution log only (console.log)
 */

function updateSubcontractorEstimatesFromRawEmails() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  const SC_EST_TARGET_SHEET_NAME = "Subcontractor Estimates";
  const SC_EST_RAW_SHEET_NAME = "HVACBizPro Raw Emails";
  const SC_EST_PMT_SHEET_NAME = "PMT Import";

  const targetSheet = ss.getSheetByName(SC_EST_TARGET_SHEET_NAME);
  if (!targetSheet) throw new Error("Missing sheet: " + SC_EST_TARGET_SHEET_NAME);

  const rawSheet = ss.getSheetByName(SC_EST_RAW_SHEET_NAME);
  if (!rawSheet) throw new Error("Missing sheet: " + SC_EST_RAW_SHEET_NAME);

  const pmtSheet = ss.getSheetByName(SC_EST_PMT_SHEET_NAME);
  if (!pmtSheet) throw new Error("Missing sheet: " + SC_EST_PMT_SHEET_NAME);

  SC_EST_ensureHeaders_(targetSheet);

  const targetLastRow = SC_EST_findLastNonEmptyRowInColumn_(targetSheet, 1, 2);
  if (targetLastRow < 2) {
    console.log("No data rows (no Job Names in column A).");
    return;
  }

  const pmtLastRow = pmtSheet.getLastRow();
  const pmtMap = SC_EST_buildPmtJobToAeMap_(pmtSheet, pmtLastRow);

  const rawLastRow = rawSheet.getLastRow();
  const rawValues = (rawLastRow >= 2)
    ? rawSheet.getRange(2, 4, rawLastRow - 1, 2).getValues()
    : [];

  console.log(
    `RUN_START updateSubcontractorEstimatesFromRawEmails | TargetRows=2-${targetLastRow} | ` +
    `PMT_Entries=${Object.keys(pmtMap).length} | RawEmails=${rawValues.length}`
  );

  for (let r = 2; r <= targetLastRow; r++) {
    const jobName = String(targetSheet.getRange(r, 1).getDisplayValue() || "").trim();

    if (!jobName) {
      targetSheet.getRange(r, 2, 1, 6).setValues([["-", "-", "-", "-", "-", "No Subcontractor"]]);
      console.log(`Row ${r} | Job="" | No Subcontractor`);
      continue;
    }

    const pmtKey = SC_EST_normKey_(jobName);
    if (Object.prototype.hasOwnProperty.call(pmtMap, pmtKey)) {
      const drillingVal = pmtMap[pmtKey];
      if (drillingVal !== 0) {
        targetSheet.getRange(r, 2, 1, 6).setValues([["-", 0, drillingVal, 0, 0, "PMT Import AE"]]);
        console.log(`Row ${r} | Job="${jobName}" | Mode=PMT_IMPORT | Drill=${drillingVal}`);
        continue;
      } else {
        console.log(`Row ${r} | Job="${jobName}" | PMT found but AE=0 -> ignoring PMT, using EMAIL parse`);
      }
    }

    const chosen = SC_EST_pickAndParseBestEmailForQuery_(jobName, rawValues, {
      requireLastNameInSubject: true,
      minTokenHits: 2,
      maxLineItem: 50000
    });

    const installAddr = chosen.installAddress || "-";

    const rowValues = SC_EST_hasAnyAmounts_(chosen.agg)
      ? [installAddr, chosen.agg.elec, chosen.agg.drill, chosen.agg.permit, chosen.agg.labor, SC_EST_dedupeSnippets_(chosen.agg.snips).join(" | ")]
      : [installAddr, "-", "-", "-", "-", "No Subcontractor"];

    targetSheet.getRange(r, 2, 1, 6).setValues([rowValues]);

    console.log(
      `Row ${r} | Job="${jobName}" | Mode=EMAIL_job | Matches=${chosen.matches} | BestScore=${chosen.bestScore} | ` +
      `AddrFound=${installAddr !== "-" ? "Y" : "N"} | Addr="${installAddr}" | ` +
      `Elec=${rowValues[1]} Drill=${rowValues[2]} Permit=${rowValues[3]} Labor=${rowValues[4]}`
    );
  }

  console.log("RUN_END updateSubcontractorEstimatesFromRawEmails");
}

/* ======================== PMT IMPORT MAP ======================== */

function SC_EST_buildPmtJobToAeMap_(pmtSheet, pmtLastRow) {
  const map = Object.create(null);
  if (pmtLastRow < 2) return map;

  const numCols = 31; // A..AE
  const vals = pmtSheet.getRange(2, 1, pmtLastRow - 1, numCols).getDisplayValues();

  for (let i = 0; i < vals.length; i++) {
    const job = String(vals[i][0] || "").trim();      // A
    const aeStr = String(vals[i][30] || "").trim();   // AE
    if (!job) continue;

    const key = SC_EST_normKey_(job);
    const aeNum = SC_EST_parseMoney_(aeStr);

    if (!Object.prototype.hasOwnProperty.call(map, key)) map[key] = aeNum;
    else if (aeNum !== 0) map[key] = aeNum;
  }

  return map;
}

function SC_EST_parseMoney_(s) {
  const x = String(s || "").replace(/[^0-9.\-]/g, "");
  const n = Number(x);
  return isFinite(n) ? n : 0;
}

function SC_EST_normKey_(s) {
  return String(s || "").toLowerCase().replace(/\s+/g, " ").trim();
}

/* ======================== PICK ONE BEST EMAIL (SCORING) ======================== */

function SC_EST_pickAndParseBestEmailForQuery_(querySource, rawValues, opts) {
  const options = opts || {};
  const minTokenHits = Number(options.minTokenHits || 2);
  const requireLastNameInSubject = !!options.requireLastNameInSubject;
  const maxLineItem = Number(options.maxLineItem || 50000);

  const queryTokens = SC_EST_tokenize_(querySource).slice(0, 6);
  const lastNameToken = SC_EST_extractLastNameToken_(querySource);

  let matches = 0;
  let bestIdx = -1;
  let bestScore = -1;

  for (let i = 0; i < rawValues.length; i++) {
    const subj = String(rawValues[i][0] || "");
    const body = String(rawValues[i][1] || "");
    if (!subj && !body) continue;

    const subjLower = subj.toLowerCase();
    const hayLower = (subj + " " + body).toLowerCase();

    if (subjLower.indexOf("financial summary :") === -1) continue;
    if (hayLower.indexOf("@") === -1) continue;
    if (hayLower.indexOf("$") === -1) continue;

    if (requireLastNameInSubject && lastNameToken) {
      if (subjLower.indexOf(lastNameToken) === -1) continue;
    }

    let hits = 0;
    let subjHits = 0;
    for (const t of queryTokens) {
      if (hayLower.indexOf(t) !== -1) hits++;
      if (subjLower.indexOf(t) !== -1) subjHits++;
    }
    if (hits < minTokenHits) continue;

    matches++;

    const lnBonus = (lastNameToken && subjLower.indexOf(lastNameToken) !== -1) ? 3 : 0;
    const score = (subjHits * 5) + (hits * 2) + lnBonus;

    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
    }
  }

  const agg = SC_EST_initAgg_();
  if (bestIdx === -1) return { agg, matches, bestScore: 0, installAddress: "" };

  const bestSubj = String(rawValues[bestIdx][0] || "");
  const bestBody = String(rawValues[bestIdx][1] || "");

  const installAddress = SC_EST_extractInstallAddressAfterLastComma_(bestBody);

  const parsed = SC_EST_categorizeAndSumByExactLines_(bestBody, maxLineItem);
  agg.elec = parsed.electricalTotal;
  agg.drill = parsed.drillingTotal;
  agg.permit = parsed.permittingTotal;
  agg.labor = parsed.laborTotal;
  agg.snips = parsed.snippets;

  console.log(
    `BestEmail | Query="${querySource}" | LastName="${lastNameToken || ""}" | ` +
    `BestScore=${bestScore} | Subject="${bestSubj}" | InstallAddress="${installAddress || ""}"`
  );

  return { agg, matches, bestScore, installAddress };
}

function SC_EST_extractInstallAddressAfterLastComma_(body) {
  const full = SC_EST_extractInstallAddressBlock_(body);
  if (!full) return "";

  // take text after the last comma
  const lastComma = full.lastIndexOf(",");
  if (lastComma === -1) return full.trim();

  return full.slice(lastComma + 1).trim();
}

/**
 * Extracts the "Install Address" block as a single line (may join up to 3 lines).
 */
function SC_EST_extractInstallAddressBlock_(body) {
  const text = String(body || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n");

  const lower = text.toLowerCase();
  const idx = lower.indexOf("install address");
  if (idx === -1) return "";

  let after = text.slice(idx + "install address".length);
  after = after.replace(/^[ \t]*[:\-–—]?[ \t]*/g, "");

  const lines = after.split("\n").map(l => l.trim());
  const stopLabelRe = /^(billing address|mailing address|install date|customer|phone|email|job name|project|scope|financial summary|total|notes)\b/i;

  const out = [];
  for (let i = 0; i < lines.length && out.length < 3; i++) {
    const l = lines[i];
    if (!l) continue;

    if (stopLabelRe.test(l)) break;
    if (/^[A-Za-z][A-Za-z \t]{2,30}:\s*/.test(l)) break;

    out.push(l);
  }

  if (!out.length) {
    const m = text.match(/Install Address\s*[:\-–—]\s*([^\n\r]+)/i);
    if (m && m[1]) return String(m[1]).trim();
    return "";
  }

  return out.join(", ").replace(/\s+/g, " ").trim();
}

function SC_EST_extractLastNameToken_(jobName) {
  const toks = SC_EST_tokenize_(jobName);
  if (!toks.length) return "";

  const stop = new Set(["install", "job", "project", "street", "avenue", "road", "drive", "lane", "court", "place", "unit"]);
  for (const t of toks) {
    if (t.length < 3) continue;
    if (stop.has(t)) continue;
    if (/^\d+$/.test(t)) continue;
    return t;
  }
  return toks[0] || "";
}

/* ======================== EXACT LINE MATCH (SLIGHT VARIATION) ======================== */

function SC_EST_categorizeAndSumByExactLines_(text, maxLineItem) {
  const normalized = String(text || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .trim();

  const items = SC_EST_extractPricedItems_(normalized, maxLineItem);

  let electricalTotal = 0;
  let drillingTotal = 0;
  let permittingTotal = 0;
  let laborTotal = 0;

  const snippets = [];

  for (const it of items) {
    const cat = SC_EST_categoryFromCanonicalSimilarity_(it.itemText);
    if (!cat) continue;

    if (cat === "electrical") electricalTotal += it.amount;
    if (cat === "drilling") drillingTotal += it.amount;
    if (cat === "permitting") permittingTotal += it.amount;
    if (cat === "labor") laborTotal += it.amount;

    snippets.push(`${cat.toUpperCase()}: ${it.rawSnippet}`);
  }

  return { electricalTotal, drillingTotal, permittingTotal, laborTotal, snippets };
}

function SC_EST_extractPricedItems_(body, maxLineItem) {
  const out = [];
  const cap = isFinite(maxLineItem) ? maxLineItem : 50000;
  const re = /@\s*\$?\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)/g;

  let m;
  while ((m = re.exec(body)) !== null) {
    const amount = Number(String(m[1]).replace(/,/g, ""));
    if (!isFinite(amount)) continue;
    if (amount > cap) continue;

    const atIndex = m.index;
    const startWindow = Math.max(0, atIndex - 260);
    let before = body.slice(startWindow, atIndex).trim();

    const lastComma = before.lastIndexOf(",");
    if (lastComma >= 0 && lastComma > before.length - 220) {
      before = before.slice(lastComma + 1).trim();
    }

    const rawSnippet = `${before} @ $${m[1]}`.replace(/\s+/g, " ").trim();
    out.push({ itemText: before, amount, rawSnippet });
  }

  return out;
}

function SC_EST_categoryFromCanonicalSimilarity_(segment) {
  const segNorm = SC_EST_normalizeLine_(segment);
  const CANON = SC_EST_getCanonicalLines_();

  const TH = { electrical: 0.88, drilling: 0.88, permitting: 0.80, labor: 0.90 };
  const MUST = {
    electrical: ["ELECTRICAL", "PERMIT"],
    drilling: ["GEOTHERMAL", "SUBCONTRACTOR"],
    permitting: ["PERMIT", "PROCESS", "HOMEOWNER"],
    labor: []
  };

  if (SC_EST_passesMustWords_(segNorm, MUST.electrical) && SC_EST_isSimilarEnough_(segNorm, SC_EST_normalizeLine_(CANON.electrical), TH.electrical)) {
    return "electrical";
  }
  if (SC_EST_passesMustWords_(segNorm, MUST.drilling) && SC_EST_isSimilarEnough_(segNorm, SC_EST_normalizeLine_(CANON.drilling), TH.drilling)) {
    return "drilling";
  }
  if (SC_EST_passesMustWords_(segNorm, MUST.permitting) && SC_EST_isSimilarEnough_(segNorm, SC_EST_normalizeLine_(CANON.permitting), TH.permitting)) {
    return "permitting";
  }

  for (const l of CANON.laborLines) {
    const ln = SC_EST_normalizeLine_(l);
    if (SC_EST_isSimilarEnough_(segNorm, ln, TH.labor)) return "labor";
  }
  return null;
}

function SC_EST_normalizeLine_(s) {
  return String(s || "")
    .toUpperCase()
    .replace(/[“”]/g, '"')
    .replace(/[’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function SC_EST_passesMustWords_(segNorm, mustWords) {
  if (!mustWords || !mustWords.length) return true;
  let hits = 0;
  for (const w of mustWords) if (segNorm.indexOf(w) !== -1) hits++;
  const need = Math.min(2, mustWords.length);
  return hits >= need;
}

function SC_EST_isSimilarEnough_(aNorm, bNorm, threshold) {
  if (!aNorm || !bNorm) return false;
  if (aNorm.indexOf(bNorm) !== -1 || bNorm.indexOf(aNorm) !== -1) return true;
  const sim = SC_EST_normalizedSimilarity_(aNorm, bNorm);
  return sim >= threshold;
}

function SC_EST_normalizedSimilarity_(a, b) {
  const dist = SC_EST_levenshtein_(a, b);
  const maxLen = Math.max(a.length, b.length) || 1;
  return 1 - (dist / maxLen);
}

function SC_EST_levenshtein_(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  const dp = new Array(n + 1);
  for (let j = 0; j <= n; j++) dp[j] = j;

  for (let i = 1; i <= m; i++) {
    let prev = dp[0];
    dp[0] = i;
    for (let j = 1; j <= n; j++) {
      const tmp = dp[j];
      const cost = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
      dp[j] = Math.min(dp[j] + 1, dp[j - 1] + 1, prev + cost);
      prev = tmp;
    }
  }
  return dp[n];
}

function SC_EST_getCanonicalLines_() {
  return {
    electrical: "ELECTRICAL PERMIT AND THIRD PARTY INSPECTION INCLUDED (GFI NOT INCLUDED)",
    drilling: "PROVIDE GEOTHERMAL WELLS WITH A LICENSED GEOTHERMAL SUBCONTRACTOR",
    permitting:
      "PERMIT PROCESS: WE WILL APPLY FOR THE PERMIT AND PASS THE COST TO THE HOMEOWNER ONCE RECEIVED. " +
      "ELECTRICAL/PLUMBING PERMITS, ENGINEERING STAMPS/DRAWINGS, AND DUCT INTEGRITY TESTS ARE NOT INCLUDED IF REQUIRED BY THE BUILDING DEPARTMENT.",
    laborLines: [
      "DECOMMISSIONING OF EXISTING HEATING SYSTEM FOR REBATE MAXIMIZATION - ADDITIONAL COST",
      "REMOVE AND DISPOSE OF PROPERLY EXISTING UNIT",
      "RE-CONNECT EXISTING DUCTWORK",
      "RE-CONNECT TO EXISTING PIPING, DUCTWORK AND ELECTRICAL",
      "RE-CONNECT EXISTING REFRIGERANT PIPING AND FLUSH OUT",
      "RE-CONNECT EXISTING OIL PIPING",
      "RE-CONNECT EXISTING FLUE PIPING",
      "RE-CONNECT EXISTING GAS PIPING",
      "RE-CONNECT EXISTING DRAIN PIPING",
      "START AND TEST COMPLETED INSTALLATION"
    ]
  };
}

/* ======================== HEADERS ======================== */

function SC_EST_ensureHeaders_(sheet) {
  const headers = ["Job Name", "Install Address", "Electrical ($)", "Drilling ($)", "Permitting ($)", "Labor ($)", "Snippets"];
  const current = sheet.getRange(1, 1, 1, headers.length).getValues()[0];

  let mismatch = current.length !== headers.length;
  if (!mismatch) {
    for (let i = 0; i < headers.length; i++) {
      if (current[i] !== headers[i]) { mismatch = true; break; }
    }
  }
  if (mismatch) sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
}

/* ======================== SNIPPET UTILS ======================== */

function SC_EST_dedupeSnippets_(snips) {
  const seen = new Set();
  const out = [];
  for (const s of snips || []) {
    const k = String(s).toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
    if (out.length >= 12) break;
  }
  return out;
}

/* ======================== TOKENS / AGG / SHEET UTILS ======================== */

function SC_EST_tokenize_(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/)
    .filter(w => w && w.length >= 3);
}

function SC_EST_initAgg_() {
  return { elec: 0, drill: 0, permit: 0, labor: 0, snips: [] };
}

function SC_EST_hasAnyAmounts_(agg) {
  return (agg.elec > 0) || (agg.drill > 0) || (agg.permit > 0) || (agg.labor > 0);
}

function SC_EST_findLastNonEmptyRowInColumn_(sheet, col, startRow) {
  const max = sheet.getMaxRows();
  const vals = sheet.getRange(startRow, col, max - startRow + 1, 1).getDisplayValues();
  for (let i = vals.length - 1; i >= 0; i--) {
    if (String(vals[i][0] || "").trim() !== "") return startRow + i;
  }
  return 0;
}

function exportProjectToJSON() {
  var scriptId = ScriptApp.getScriptId();
  var url = "https://script.googleapis.com/v1/projects/" + scriptId + "/content";

  var response = UrlFetchApp.fetch(url, {
    method: "get",
    headers: {
      Authorization: "Bearer " + ScriptApp.getOAuthToken()
    }
  });

  var content = JSON.parse(response.getContentText());

  var exportData = {
    scriptId: scriptId,
    exportedAt: new Date().toISOString(),
    files: content.files || []
  };

  var json = JSON.stringify(exportData, null, 2);

  var html = `
    <html>
      <body>
        <a id="download" download="appscript-project.json"
           href="data:application/json;charset=utf-8,${encodeURIComponent(json)}">
        </a>
        <script>
          document.getElementById('download').click();
        </script>
      </body>
    </html>
  `;

  var output = HtmlService.createHtmlOutput(html);
  SpreadsheetApp.getUi().showModalDialog(output, "Download JSON");
}
